#!/bin/bash
# Build the hand-written PTX kernels to cubin with ptxas.
#
# Usage: ./build_ptx.sh [sm_75|sm_80|sm_86|sm_90] [ILP=1|2|4]
#
# sha256_pow.ptx is compiled as-is. sha256_opt.ptx is generated for the
# requested ILP by gen_opt_ptx.py (the checked-in file is the ILP=2 output).
# hashx_interp.ptx is the HashX interpreter, generated by gen_hashx_ptx.py.
set -euo pipefail

PTXAS="${PTXAS:-ptxas}"
ARCH="${1:-sm_75}"
ILP="${2:-2}"
SRC_DIR="$(cd "$(dirname "$0")" && pwd)"
OUT_DIR="$SRC_DIR/cubin"
mkdir -p "$OUT_DIR"

echo "Building PTX for $ARCH (ILP=$ILP) using $PTXAS"

echo "Compiling sha256_pow.ptx..."
"$PTXAS" -arch="$ARCH" -o "$OUT_DIR/sha256_pow.cubin" "$SRC_DIR/sha256_pow.ptx"

echo "Generating and compiling sha256_opt.ptx (ILP=$ILP)..."
TMP="$OUT_DIR/sha256_opt_ilp${ILP}.ptx"
python3 "$SRC_DIR/gen_opt_ptx.py" --ilp "$ILP" > "$TMP"
"$PTXAS" -arch="$ARCH" -o "$OUT_DIR/sha256_opt_ilp${ILP}.cubin" "$TMP"
rm -f "$TMP"

echo "Generating and compiling hashx_interp.ptx..."
python3 "$SRC_DIR/gen_hashx_ptx.py" > "$OUT_DIR/hashx_interp.ptx"
"$PTXAS" -arch="$ARCH" -o "$OUT_DIR/hashx_interp.cubin" "$OUT_DIR/hashx_interp.ptx"
rm -f "$OUT_DIR/hashx_interp.ptx"

echo "Done. Cubins in $OUT_DIR:"
ls -la "$OUT_DIR/"

if command -v nvdisasm &>/dev/null; then
    echo ""
    echo "sha256_opt_ilp${ILP}.cubin (first 40 instructions):"
    # `head` closes the pipe, so nvdisasm dies of SIGPIPE (141) and `pipefail`
    # would turn a successful build into a failure. Truncate without a pipe.
    nvdisasm -c "$OUT_DIR/sha256_opt_ilp${ILP}.cubin" 2>/dev/null \
        | sed -n '1,40p' || true
fi
